    ("Units", "units_sondes", "Radiosondes: Units (Site Default)", "select", "The unit set the Radiosondes pages start with for anyone who has not chosen their own (in the Display menu, for this service or overall). SondeHub shows balloons in meters, km/h and m/s. Standard means the Site Default above (Settings > Home Page and Live Map).", {"choices": [("", "Standard"), ("imperial", "Imperial: feet, mph, miles, F"), ("aero", "Aeronautical: feet, knots, nautical miles, C"), ("metric", "Metric: meters, km/h, kilometers, C")]}),
    ("Units", "units_aprs", "APRS: Units (Site Default)", "select", "The unit set the APRS pages start with for anyone who has not chosen their own (in the Display menu, for this service or overall). APRS is a US amateur radio network that reports feet, mph and degrees F. Standard means the Site Default above (Settings > Home Page and Live Map).", {"choices": [("", "Standard"), ("imperial", "Imperial: feet, mph, miles, F"), ("aero", "Aeronautical: feet, knots, nautical miles, C"), ("metric", "Metric: meters, km/h, kilometers, C")]}),
    ("Units", "units_acars", "ACARS: Units (Site Default)", "select", "The unit set the ACARS pages start with for anyone who has not chosen their own (in the Display menu, for this service or overall). ACARS is aviation: feet and knots. Standard means the Site Default above (Settings > Home Page and Live Map).", {"choices": [("", "Standard"), ("imperial", "Imperial: feet, mph, miles, F"), ("aero", "Aeronautical: feet, knots, nautical miles, C"), ("metric", "Metric: meters, km/h, kilometers, C")]}),
