    ("Units", "units_repeaters", "Repeaters: Units (Site Default)", "select", "The unit set the Repeaters pages start with for anyone who has not chosen their own (in the Display menu, for this service or overall). US repeater directories use miles. Standard means the Site Default above (Settings > Home Page and Live Map).", {"choices": [("", "Standard"), ("imperial", "Imperial: feet, mph, miles, F"), ("aero", "Aeronautical: feet, knots, nautical miles, C"), ("metric", "Metric: meters, km/h, kilometers, C")]}),
    ("Units", "units_places", "Places and Counties: Units (Site Default)", "select", "The unit set the Places and Counties pages start with for anyone who has not chosen their own (in the Display menu, for this service or overall). US maps use miles and feet. Standard means the Site Default above (Settings > Home Page and Live Map).", {"choices": [("", "Standard"), ("imperial", "Imperial: feet, mph, miles, F"), ("aero", "Aeronautical: feet, knots, nautical miles, C"), ("metric", "Metric: meters, km/h, kilometers, C")]}),
    ("Units", "units_network", "Coverage, Feeders and MLAT: Units (Site Default)", "select", "The unit set the Coverage, Feeders and MLAT pages start with for anyone who has not chosen their own (in the Display menu, for this service or overall). The ADS-B network measures range in nautical miles. Standard means the Site Default above (Settings > Home Page and Live Map).", {"choices": [("", "Standard"), ("imperial", "Imperial: feet, mph, miles, F"), ("aero", "Aeronautical: feet, knots, nautical miles, C"), ("metric", "Metric: meters, km/h, kilometers, C")]}),
    ("Units", "units_home", "Home Page: Units (Site Default)", "select", "The unit set the Home Page pages start with for anyone who has not chosen their own (in the Display menu, for this service or overall). Mixed: the standard unit. Standard means the Site Default above (Settings > Home Page and Live Map).", {"choices": [("", "Standard"), ("imperial", "Imperial: feet, mph, miles, F"), ("aero", "Aeronautical: feet, knots, nautical miles, C"), ("metric", "Metric: meters, km/h, kilometers, C")]}),
    ("Home Page and Live Map", "live_units", "Units (Site Default)", "select",
     "The units every page uses (altitude, speed, distance, temperature, and the distance settings in Admin) for anyone who has not chosen their own in the Display menu. Imperial: feet, mph, miles, degrees F. Aeronautical: feet, knots, nautical miles, degrees C. Metric: meters, km/h, kilometers, degrees C. Each person's choice is saved with their account.", {"choices": UNIT_CHOICES}),
    ("Scheduled Updates", "update_now_wait_seconds", "Update Now: Wait for the Answer (Seconds)", "int",
     "When an administrator presses Update Now, the portal asks the update service (Watchtower) and waits this long for its answer. If the portal itself is being replaced the answer never arrives, and the page says the update has started. The button appears only when the update service is set up on the hub.", {"lo": 5, "hi": 120}),
    ("Scheduled Updates", "airports_update_days", "Update Airport Data Every (Days)", "int",
     "How often the airport list, frequencies and runways are downloaded again from OurAirports, using the countries chosen on the Airports page. 0 turns automatic updates off.", {"lo": 0, "hi": 365}),
    ("Radiosondes", "sonde_enabled", "Radiosondes and Balloons", "select",
     "Switches the whole service on or off: the pages, the menu, the home page card and the map layers. Off keeps the stored flights but shows nothing.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Radiosondes", "sonde_live_enabled", "Read the Live Feed", "select",
     "Whether this portal listens to SondeHub's live feed. Off stops new flights from arriving but keeps the pages and what is stored.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Radiosondes", "sonde_amateur_enabled", "Include Amateur Balloons", "select",
     "On: high-altitude balloons flown by amateurs (SondeHub's amateur feed) are recorded and shown next to the National Weather Service radiosondes, marked as amateur. National Weather Service flights are always included.", {"choices": [("1", "On"), ("0", "Off (weather service balloons and other radiosondes only)")]}),
    ("Radiosondes", "sonde_api_url", "SondeHub Address", "httpsurl",
     "The SondeHub API. The portal reads its live feed (one connection) and asks it for a flight's start and for the launch-site list only; it never polls it. Data is licensed Creative Commons BY-SA 2.0 and credited on every page.", {}),
    ("Radiosondes", "sonde_regions", "Area to Record", "text",
     "Rectangles in decimal degrees, south,west,north,east, separated by semicolons. A flight is recorded once any of its positions is inside one (and then followed everywhere). The default covers Arkansas, Missouri, Tennessee, Mississippi, Louisiana, Texas and Oklahoma.", {"max": 600}),
    ("Radiosondes", "sonde_keep_every_seconds", "Keep a Position at Most Every (Seconds)", "int",
     "Radiosondes send a position about every second. The portal stores one every this many seconds per flight, which keeps the track and the charts and keeps the database small.", {"lo": 1, "hi": 120}),
    ("Radiosondes", "sonde_full_days", "Keep Full Detail For (Days)", "int",
     "Flights newer than this keep every stored position; older ones are thinned to one position every Thin to Seconds. 0 never thins.", {"lo": 0, "hi": 3650}),
    ("Radiosondes", "sonde_thin_seconds", "Thin Older Flights to One Position Every (Seconds)", "int",
     "How sparse an old flight's track becomes after the full-detail period.", {"lo": 5, "hi": 600}),
    ("Radiosondes", "sonde_keep_days", "Delete Positions Older Than (Days)", "int",
     "Positions older than this are deleted (the flight, its launch, burst and landing stay in the list). 0 keeps them for good.", {"lo": 0, "hi": 36500}),
    ("Radiosondes", "sonde_nws_pattern", "National Weather Service Site Numbers", "text",
     "A launch site is a National Weather Service site when its WMO station number matches this pattern (a regular expression; the default matches 72xxx and 74xxx). Flights from those sites are marked NWS.", {"max": 80}),
    ("Radiosondes", "sonde_nws_exclude", "Not National Weather Service (Site Numbers)", "text",
     "Site numbers that match the pattern above but are run by someone else, separated by commas (74646 is the Department of Energy's research site in Oklahoma).", {"max": 200, "optional": True}),
    ("Radiosondes", "sonde_site_match_km", "Launch Site Match Distance", "dist",
     "A flight whose first position is within this distance of a launch site, and low, is a launch from that site.", {"base": "km", "lo": 2, "hi": 100}),
    ("Radiosondes", "sonde_stale_minutes", "Flight Over After (Minutes)", "int",
     "A flight not heard for this long is finished: landed if it was low, signal lost if it was high.", {"lo": 2, "hi": 240}),
    ("Radiosondes", "sonde_landed_below_m", "Counts as Landed Below", "dist",
     "The last altitude below which a flight that went quiet is called landed rather than lost at height.", {"base": "m", "lo": 100, "hi": 12000}),
    ("Radiosondes", "sonde_backfill", "Fetch the Start of Late-Joined Flights", "select",
     "A flight first heard after it left the ground has its earlier positions fetched once from SondeHub (one request per flight, a few seconds apart) so the whole track and the launch site are known.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Radiosondes", "sonde_station_privacy", "Receiving Station Location Until Claimed", "select",
     "How precisely a receiving station's position is shown until its owner chooses. Stations that move (chasers) are always hidden unless their owner picks Exact.", {"choices": privacy.choices(skip=("exact",))}),
    ("Radiosondes", "sonde_claim_mode", "Claiming a Receiving Station", "select",
     "Match: a member whose profile call sign matches the station's claims it at once. Otherwise (or always, with Proof): the member puts a short code in the station's antenna description and the live feed completes the claim, or an administrator approves it.", {"choices": [("match", "Matching call sign is enough"), ("proof", "Always require the code or an administrator")]}),
    ("Radiosondes", "sonde_auto_claim", "Claim Stations Automatically", "select",
     "On (with Matching call sign above): a receiving station whose call sign, without a suffix such as -LR, -10 or /P, is the profile call sign of exactly one member is claimed for that member by itself (when the station is first heard, and whenever the member opens My Radiosonde Stations). Off: members claim each station themselves.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Radiosondes", "sonde_overview_states", "Radiosondes Overview Shows", "collist",
     "The states whose balloons and receiving stations the Radiosondes overview page lists and counts. Arkansas only by default. A balloon belongs to the state it was launched in (or, when that is not known, where it was last heard); \"Anywhere else\" is everything outside Arkansas and its neighbors. The Radiosonde Map and the flight lists still offer everything the site records.",
     {"choices": [("AR", "Arkansas"), ("MO", "Missouri"), ("TN", "Tennessee"), ("MS", "Mississippi"), ("LA", "Louisiana"), ("TX", "Texas"), ("OK", "Oklahoma"), ("-", "Anywhere else")]}),
    ("Radiosondes", "sonde_report_mode", "Members Report Recoveries to SondeHub", "select",
     "Signed-in members can report a recovered, planned or not-found balloon from its flight page; the report is sent to SondeHub in the tracker's own format and becomes public there (SondeHub data is CC BY-SA 2.0). Test keeps the report on this site only and sends nothing, to try it out. Off hides the form.", {"choices": [("1", "On"), ("test", "Test (send nothing)"), ("0", "Off")]}),
    ("Prediction Service", "predict_enabled", "Use the Prediction Service", "select",
     "Shows forecasts of where the balloons of upcoming launches will land, and the archive history behind them, from the separate prediction service container (its own database). Off hides them; the rest of the site is unaffected.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Prediction Service", "predict_url", "Prediction Service Address", "httpsurl",
     "Where the prediction service answers: http://predict:8470 when it runs beside the portal on the hub, or the address of another machine if you moved it.", {}),
    ("Prediction Service", "predict_sites", "Launch Sites to Import and Forecast", "text",
     "Weather service launch site numbers, separated by commas (72340 is Little Rock). The defaults are Little Rock and the sites around Arkansas. Each adds about 700 flights a year to the history. Sent to the service when you press Apply on Admin > Radiosondes.", {"max": 400}),
    ("Prediction Service", "predict_since", "Import History Back To", "text",
     "The oldest date (year-month-day) the archive import goes back to, newest first. SondeHub's launch site archive starts in 2022.", {"max": 10}),
    ("Prediction Service", "predict_rate", "Import Requests Per Second", "float",
     "How fast the service asks SondeHub's archive for flights. Slow and steady is polite; 4 imports the whole default list in a few hours.", {"lo": 0.2, "hi": 20}),
    ("Prediction Service", "predict_date_mode", "Also Scan the World by Date (2018 On)", "select",
     "Adds a slow scan of the worldwide day-by-day archive from 2018, keeping flights that launched in the area around Arkansas. It makes one request for every flight in the world, so it takes days; the launch site import above is usually enough.", {"choices": [("0", "Off"), ("1", "On")]}),
    ("Prediction Service", "predict_auto_import", "Import Again Every Day", "select",
     "Lets the service bring the history up to date by itself once a day.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Prediction Service", "predict_methods", "Forecast Methods Kept for Every Coming Launch", "text",
     "Which predictors the service works out and scores against the real flights, separated by commas: statistical (past flights of the same site, season and hour), wind (our own flight model through forecast winds) and tawhiri (needs the address below). Everyone can pick among them on the Radiosonde Map.", {}),
    ("Prediction Service", "predict_default_method", "Predictor Shown by Default", "select",
     "The predictor a visitor sees until they choose another on the Radiosonde Map (their choice is kept in their browser).", {"choices": [("statistical", "Past flights (statistical)"), ("wind", "Forecast winds (our model)"), ("tawhiri", "Tawhiri")]}),
    ("Prediction Service", "predict_wind_source", "Forecast Winds From", "select", "Where the wind predictor gets the winds by height: our own reading of NOAA's GFS model (kept in the service, for the area chosen below) when it is fresh and Open-Meteo otherwise (Automatic), only ours, or only Open-Meteo.",
     {"choices": [("auto", "Automatic: our own GFS data, else Open-Meteo"), ("gfs", "Our own GFS data only"), ("openmeteo", "Open-Meteo only")]}),
    ("Prediction Service", "predict_gfs_enabled", "Read NOAA GFS Ourselves", "select", "The service reads NOAA's GFS weather model (winds by height and the surface forecast) for a box around Arkansas, a new cycle every six hours, for the wind predictor and for the model forecast on Weather for a Place.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Prediction Service", "predict_gfs_box", "GFS Area (South, West, North, East)", "text", "The box of the model that is kept, in degrees, as south,west,north,east (at most 40 degrees tall and 50 wide). The default covers Arkansas with a wide margin so balloons can be followed far from home.", {"max": 60}),
    ("Prediction Service", "predict_gfs_hours", "GFS Forecast Hours Kept", "int", "How far ahead the model is kept, in hours (every three hours). The winds are only used within the wind forecast horizon; the model forecast page uses all of it.", {"lo": 12, "hi": 120}),
    ("Prediction Service", "predict_gfs_refresh_minutes", "Look for a New GFS Cycle Every (Minutes)", "int", "How often the service checks whether NOAA has published a newer cycle (a cycle appears about every six hours, a few hours after its nominal time).", {"lo": 15, "hi": 720}),
    ("Prediction Service", "wx_model_forecast", "Show the Model Forecast on Weather for a Place", "select", "An hour-by-hour forecast from our own GFS data below the National Weather Service forecast. Needs the prediction service and its GFS data.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Prediction Service", "predict_wind_url", "Forecast Winds Source", "httpsurl",
     "The Open-Meteo GFS endpoint the wind predictor reads (one request per launch site and hour, kept for the time below). Open-Meteo's free service is for non-commercial use with attribution; their commercial address and key can go here instead.", {}),
    ("Prediction Service", "predict_wind_cache_hours", "Keep Forecast Winds For (Hours)", "float",
     "A wind column (a quarter degree, one hour) is reused for this long so the same one is never asked for twice.", {"lo": 1, "hi": 12}),
    ("Prediction Service", "predict_wind_horizon_hours", "Winds Only for Launches Within (Hours)", "int",
     "Wind and Tawhiri forecasts are worked out only for launches this close; further ahead the winds are not worth asking for.", {"lo": 6, "hi": 120}),
    ("Prediction Service", "predict_wind_refresh_hours", "Work Wind Forecasts Out Again After (Hours)", "float",
     "A wind forecast is kept this long before it is worked out again; the weather models themselves update every six hours. Keeps the number of outside requests low.", {"lo": 1, "hi": 24}),
    ("Prediction Service", "predict_wind_max_per_day", "Most Wind Requests per Day", "int",
     "A hard limit on the requests the service makes to the wind source in a day; it also stops for an hour if the source answers 'too many requests'.", {"lo": 50, "hi": 20000}),
    ("Prediction Service", "predict_descent_ms", "Parachute Fall Speed Near the Ground (m/s)", "float",
     "Used by the wind predictor; it falls faster in thin air.", {"lo": 3, "hi": 12}),
    ("Prediction Service", "predict_tawhiri_url", "Tawhiri Predictor Address", "httpsurl",
     "Leave empty to not offer Tawhiri. SondeHub hosts one (https://api.v2.sondehub.org/tawhiri) but asks other applications to contact them first and allows non-commercial use only; a Tawhiri server run by the site itself also works. Press Apply on Admin > Radiosondes after a change.", {"optional": True}),
    ("Prediction Service", "predict_horizon_hours", "Forecast Launches Ahead (Hours)", "int",
     "How far ahead the usual launch times are forecast. Winds are only trusted for a couple of days.", {"lo": 12, "hi": 240}),
    ("Prediction Service", "predict_lookback_days", "Forecast From Flights In The Last (Days)", "int",
     "How much history the forecasts draw on (1825 is five years).", {"lo": 60, "hi": 4000}),
    ("Prediction Service", "predict_season_days", "Same Season Window (Days)", "int",
     "Past flights within this many days of the same date in other years count as the same season.", {"lo": 7, "hi": 120}),
    ("Prediction Service", "predict_persist_hours", "Latest Flights Count For (Hours)", "int",
     "Winds persist: flights from the same site this recently pull the forecast toward where they went.", {"lo": 6, "hi": 120}),
    ("Prediction Service", "predict_map_hours", "Map Shows Launches Within (Hours)", "int",
     "The Radiosonde Map shows forecast landing areas for launches this soon.", {"lo": 3, "hi": 120}),
    ("Radiosondes", "sonde_history_enabled", "Bring In Historical Flights", "select",
     "Brings in every flight SondeHub's archive holds for the launch sites below, as full flights like the ones recorded live, slowly and in the background (one request per flight, a pause between). Switch it on once and leave it on: it works newest month first, remembers what is done and picks up new flights each day. Admin > Radiosondes shows the progress.", {"choices": [("0", "Off"), ("1", "On")]}),
    ("Radiosondes", "sonde_history_sites", "Historical Flights From Launch Sites", "text",
     "Weather service launch site numbers, separated by commas: Little Rock (72340) and the sites around Arkansas (Shreveport 72248, Jackson 72235, Springfield MO 72440, Norman 72357, Fort Worth 72249, Nashville 72327 by default).", {"max": 300}),
    ("Radiosondes", "sonde_history_since", "Historical Flights Back To", "text",
     "The oldest date (year-month-day) to go back to. SondeHub's launch site archive starts in 2022.", {"max": 10}),
    ("Radiosondes", "sonde_history_thin_seconds", "Historical Flights: One Position Every (Seconds)", "int",
     "Historical flights keep one position this often (a live flight keeps one every few seconds). 30 gives about 250 positions for a flight of two and a half hours.", {"lo": 5, "hi": 300}),
    ("Radiosondes", "sonde_history_pause_seconds", "Historical Flights: Pause Between Flights (Seconds)", "float",
     "How long the job waits after each flight, to be gentle with SondeHub's archive.", {"lo": 0.0, "hi": 60.0}),
    ("Radiosondes", "sonde_archive_enabled", "Members Can Load a Flight by Serial", "select",
     "Lets signed-in members type a serial on the Balloon Flights page and load that flight from SondeHub's public archive (one request per click, never polled). The flight is then kept here like any other.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Radiosondes", "sonde_archive_url", "SondeHub Archive Address", "httpsurl",
     "Where SondeHub's open data archive lives (an anonymous AWS bucket). Change it only if SondeHub moves it.", {}),
    ("Radiosondes", "sonde_archive_max_mb", "Largest Archive File to Load (MB)", "int",
     "A flight's archive file bigger than this is refused. Long flights seen by many stations run to tens of megabytes.", {"lo": 5, "hi": 300}),
    ("Radiosondes", "sonde_archive_per_hour", "Archive Loads Per Member Per Hour", "int",
     "The most flights one member can load from the archive in an hour.", {"lo": 1, "hi": 60}),
    ("Radiosondes", "sonde_report_per_hour", "Recovery Reports Per Member Per Hour", "int",
     "The most recovery reports one member can send in an hour.", {"lo": 1, "hi": 60}),
    ("Radiosondes", "sonde_chase_mode", "Chase Mode Sharing to SondeHub", "select",
     "Chase mode on the Radiosonde Map is for signed-in members: their own position, the distance and bearing to a balloon, and the chase cars. This setting is only about members who also switch on Share My Position, which sends their car (CALLSIGN_chase, from their profile call sign) to SondeHub's map. Test sends nothing. Off hides sharing; chase mode itself stays.", {"choices": [("1", "On"), ("test", "Test (send nothing)"), ("0", "Off")]}),
    ("Radiosondes", "sonde_chase_min_seconds", "Chase Car Updates Every (Seconds)", "int",
     "A shared car position is sent to SondeHub at most this often.", {"lo": 5, "hi": 300}),
    ("Radiosondes", "sonde_chase_max_hours", "Share a Chase Car for at Most (Hours)", "int",
     "Sharing stops this long after it was switched on, so a forgotten browser tab does not share a position all day.", {"lo": 1, "hi": 24}),
    ("Radiosondes", "sonde_chase_cars_minutes", "Show Chase Cars Heard in the Last (Minutes)", "int",
     "Chase cars on SondeHub's feed that have reported within this time are shown to signed-in members in chase mode.", {"lo": 5, "hi": 240}),
    ("Radiosondes", "sonde_recovery_minutes", "Read Recovery Reports Every (Minutes)", "int",
     "How often the portal asks SondeHub, with one request, for the reports people file when they found a sonde or looked and did not. 0 turns it off. Never faster than 15 minutes.", {"lo": 0, "hi": 1440}),
    ("Radiosondes", "sonde_recovery_days", "Recovery Reports From the Last (Days)", "int",
     "How far back each reading of the recovery reports goes.", {"lo": 1, "hi": 90}),
    ("Radiosondes", "sonde_recovery_radius_km", "Recovery Reports Within", "dist",
     "Reports are read for flights within this distance of the middle of the area to record.", {"base": "km", "lo": 100, "hi": 3000}),
    ("Radiosondes", "sonde_max_per_user", "Receiving Stations Per Member", "int",
     "How many receiving stations one account may claim.", {"lo": 1, "hi": 50}),
    ("Radiosondes", "sonde_live_seconds", "Balloon Pages Update Every (Seconds)", "int",
     "How often an open balloon map or flight page asks for fresh positions.", {"lo": 5, "hi": 300}),
    ("Radiosondes", "sonde_map_hours", "Radiosonde Map Shows Flights From the Last (Hours)", "int",
     "The time window the balloon map opens with; visitors can choose another (up to the longest window below).", {"lo": 1, "hi": 720}),
    ("Radiosondes", "sonde_map_max_hours", "Radiosonde Map Longest Window (Hours)", "int",
     "The longest \"flights from the last\" window the balloon map offers (48 by default). Anything older is loaded as history with a From and To date.", {"lo": 1, "hi": 720}),
    ("Radiosondes", "sonde_history_max_days", "Radiosonde Map History Range Limit (Days)", "int",
     "The most days one From and To history request may cover (the map draws at most 400 flights of the range).", {"lo": 1, "hi": 366}),
    ("Radiosondes", "sonde_trail_points", "Track Points per Balloon on the Maps", "int",
     "About how many points the maps draw for a balloon's whole track (a long flight is thinned evenly, so its start is never cut off).", {"lo": 20, "hi": 3000}),
    ("Radiosondes", "sonde_trail_step_seconds", "Map Track Spacing (Seconds)", "int",
     "The least time between the track points the maps draw (the flight page uses every stored point).", {"lo": 5, "hi": 600}),
    ("Radiosondes", "sonde_county_all_sites", "County Pages List Every Launch Site", "select",
     "Off: a county page lists National Weather Service launch sites. On: research and other sites too.", {"choices": [("0", "Weather service only"), ("1", "All sites")]}),
    ("Radiosondes", "sonde_home_card", "Balloons Card on the Home Page", "select",
     "Shows balloons currently over Arkansas on the home page.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Scheduled Updates", "sondesites_update_days", "Update Balloon Launch Sites Every (Days)", "int",
     "How often the launch-site list is read again from SondeHub. 0 turns automatic updates off.", {"lo": 0, "hi": 365}),
    ("Scheduled Updates", "counties_update_days", "Update County Outlines Every (Days)", "int",
     "How often the county shapes are downloaded again from the Census Bureau. 0 turns automatic updates off. Counties change almost never, so a yearly check is plenty.", {"lo": 0, "hi": 730}),
    ("Scheduled Updates", "places_update_days", "Update Places Every (Days)", "int",
     "How often the Census cities, ZIP areas and counties are downloaded again. 0 turns automatic updates off. All schedules are on Admin > Data Updates too.", {"lo": 0, "hi": 365}),
    ("Scheduled Updates", "hospitals_update_days", "Update Hospitals Every (Days)", "int",
     "How often the hospital list is downloaded again (with the type filter and new addresses located). 0 turns automatic updates off.", {"lo": 0, "hi": 365}),
    ("Scheduled Updates", "trauma_update_days", "Update Trauma Levels Every (Days)", "int",
     "How often the trauma level and services list is read again from its source address (set on Admin > Data Updates). 0 turns automatic updates off.", {"lo": 0, "hi": 365}),
    ("Scheduled Updates", "traumasystem_update_days", "Update The Trauma System Every (Days)", "int",
     "How often the state's list of designated trauma centers is applied to the hospitals and which hospitals the Trauma Map shows is worked out again (0 turns it off).", {"lo": 0, "hi": 365}),
    ("Scheduled Updates", "placemedia_update_days", "Look Up Websites and Pictures Every (Days)", "int",
     "How often the websites and pictures of hospitals and counties are looked up again in Wikidata and Wikimedia Commons (0 turns it off). Anything an administrator typed in is never replaced.", {"lo": 0, "hi": 365}),
    ("Hospitals", "trauma_border_minutes", "Trauma Map: Hospitals Near The State Line (Minutes)", "int",
     "The Trauma Map also shows a hospital in a neighboring state when it is this many minutes or fewer by road from the Arkansas state line (our own estimate from the routing server).", {"lo": 0, "hi": 240}),
    ("Hospitals", "trauma_border_fallback_km", "Trauma Map: State Line Distance Without Routing", "dist",
     "When the routing server is off or does not answer, a hospital in a neighboring state is shown if it is this close or closer in a straight line to the state line.", {"base": "km", "lo": 0, "hi": 400}),
    ("Hospitals", "trauma_emergency_only", "Trauma Map: Only Hospitals With An Emergency Department", "select",
     "On: the Trauma Map shows the hospitals of Arkansas that have an emergency department, plus every designated trauma center. Off: every hospital of the state.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Hospitals", "trauma_hospital_states", "Trauma Map: Home State", "text",
     "The state whose trauma system the Trauma Map shows (the two-letter code; Arkansas for now).", {"max": 20}),
    ("Hospitals", "trauma_wikidata_url", "Wikidata Query Address", "httpsurl",
     "Where websites and pictures of hospitals and counties are looked up (Wikidata, free, credited).", {}),
    ("Hospitals", "trauma_overpass_url", "OpenStreetMap Query Address (Overpass)", "httpsurl",
     "Where a hospital's website is looked up when Wikidata has none (OpenStreetMap contributors, ODbL, credited; one query per run).", {}),
    ("Hospitals", "trauma_commons_url", "Wikimedia Commons Address", "httpsurl",
     "Where the author and license of a picture are read (Wikimedia Commons, shown with the picture).", {}),
    ("Weather Stations", "wx_stats_enabled", "Keep Weather Statistics", "select",
     "Keeps a reading of every weather station that reports (members, APRS and airports) every few minutes, so the Weather Statistics page can chart and filter them by area, station and source.", {"choices": [("1", "On"), ("0", "Off")]}),
    ("Weather Stations", "wx_stats_minutes", "Weather Statistics Reading Every (Minutes)", "int",
     "How often a reading of every reporting station is kept for the statistics.", {"lo": 2, "hi": 120}),
