from .features import FEATURES as _F, POLICIES as _P   # noqa: E402

for _key, _label, _sw, _manage in _F:
    SPECS.append(("Feature Access", "access_" + _key, "Who Can See " + _label, "select", "Who can see " + _label + " (its pages, menu entries, How to Feed page, map layer and everything else about it). Everyone is the default. Signed-in members only hides it from visitors who are not signed in. Only members whose role has the See " + _label + " permission (Admin > Roles) hides it from everyone else; the people who run it always see it.", {"choices": [(v, l.replace("See permission", "See " + _label + " permission")) for v, l in _P]}))


def _private_host(host):
    if host == "localhost" or (host and "." not in host and not host.isdigit()):   # a one-word name is a docker or LAN host (photon, osrm)
        return True
    try:
        ip = ipaddress.ip_address(host)
        return ip.is_private or ip.is_loopback
    except ValueError:
        return False


def validate(key, kind, label, raw, extra):
    """Return (clean value, error)."""
    raw = (raw or "").strip()
    if kind == "int":
        if not (raw.lstrip("-").isdigit() and extra["lo"] <= int(raw) <= extra["hi"]):
            return None, f"{label} must be a whole number from {extra['lo']} to {extra['hi']}."
        return str(int(raw)), None
    if kind == "time":
        if not re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", raw):
            return None, f"{label} must be a 24-hour time such as 03:30."
        return raw, None
    if kind == "float":
        try:
            ok = extra["lo"] <= float(raw) <= extra["hi"]
        except ValueError:
            ok = False
        if not ok:
            return None, f"{label} must be a number from {extra['lo']} to {extra['hi']}."
        return str(float(raw)).rstrip("0").rstrip("."), None
    if kind == "dist":
        from .units import parse
        v, err = parse(raw, extra["base"])
        if err:
            return None, f"{label}: {err}"
        if not (extra["lo"] <= v <= extra["hi"]):
            from .units import fmt
            return None, f"{label} must be between {fmt(extra['lo'], extra['base'])} and {fmt(extra['hi'], extra['base'])}."
        return str(v).rstrip("0").rstrip(".") if "." in str(v) else str(v), None
    if kind == "bounds":
        try:
            sv, wv, nv, ev = [float(x) for x in raw.split(",")]
        except ValueError:
            return None, f"{label} must be four numbers separated by commas: south, west, north, east."
        if not (-85 <= sv < nv <= 85 and -180 <= wv < ev <= 180) or nv - sv > 60 or ev - wv > 120:
            return None, f"{label} must run from south to north (-85 to 85) and from west to east (-180 to 180) and not be larger than a continent."
        return ",".join(str(x).rstrip("0").rstrip(".") if "." in str(x) else str(x) for x in (sv, wv, nv, ev)), None
    if kind == "select":
        if raw not in dict(extra["choices"]):
            return None, f"Choose a valid {label}."
        return raw, None
    if kind == "collist":
        picked = [c for c in raw.split(",") if c]
        if not picked or any(c not in dict(extra["choices"]) for c in picked):
            return None, f"Choose at least one valid column for {label}."
        return ",".join(k for k, _ in extra["choices"] if k in picked), None
    if kind == "hostname":
        raw = raw.strip().lower()
        if not raw and extra.get("optional"):
            return "", None
        if not re.match(r"^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$", raw) or "." not in raw:
            return None, f"{label} must be a host name such as arksignal.net."
        return raw, None
    if kind == "text":
        if not raw and extra.get("optional"):
            return "", None
        if not raw or len(raw) > extra.get("max", 200):
            return None, f"{label} must be between 1 and {extra.get('max', 200)} characters."
        return raw, None
    if not raw and kind == "httpsurl" and extra.get("optional"):
        return "", None
    u = urlparse(raw)
    ok_scheme = u.scheme == "https" or (u.scheme == "http" and _private_host(u.hostname or ""))
    if not raw or not u.netloc or not ok_scheme or " " in raw or len(raw) > 300:
        return None, f"{label} must be a full https:// address (plain http only for a private network)."
    if kind == "tileurl" and not all(t in raw for t in ("{z}", "{x}", "{y}")):
        return None, f"{label} must contain {{z}}, {{x}} and {{y}}."
    if extra.get("slash") and not raw.endswith("/"):
        return None, f"{label} must end with a slash."
    if kind == "httpsurl" and not extra.get("slash"):
        raw = raw.rstrip("/") if key_is_base(key) else raw
    return raw, None


def key_is_base(key):
    return key in ("leaflet_base_url", "maplibre_base_url")
